(()=>{'use strict';
 const labels={Fame:'Слава (опыт)',ReSpec:'Свободная слава',Silver:'Серебро',Might:'Могущество',Favor:'Благосклонность',FactionStanding:'Фракционная репутация',FactionPoints:'Очки фракции',RepairCosts:'Ремонт',PaidSilverForReSpec:'Расходы на автоизучение',BrecilianStanding:'Репутация Бресилиена',LootValue:'Стоимость добычи',LootedChest:'Открыто сундуков',ItemQualityRerollCosts:'Перековка качества',ItemQualityRerollResult:'Улучшено предметов',ItemQualityRerollAttempt:'Попыток улучшения',AwakenedWeaponCosts:'Расходы на пробуждение',AwakenedWeaponTraitUpgrade:'Улучшения пробуждения',AwakenedWeaponTraitUpgradeProc:'Удачные улучшения',PlayerKill:'Убийства игроков',PlayerDeath:'Смерти',MobKill:'Убито существ',PlayerKnockout:'Нокауты противников',PlayerKnockedOut:'Получено нокаутов',localDamage:'Личный урон',localTakenDamage:'Полученный урон',localHeal:'Лечение',localHealingReceived:'Получено лечения',localOverheal:'Избыточное лечение',partyDamage:'Урон группы',partyHeal:'Лечение группы',partyTakenDamage:'Полученный урон группы',partyOverheal:'Избыточное лечение группы'};
 const modules={statistics:'Обзор и история',combat:'Бой',gathering:'Собирательство',dungeons:'Подземелья',trade:'Торговля',storage:'Хранилища',crafting:'Крафт',locations:'Перемещения',loot:'Добыча',guild:'Гильдия',party:'Группа',character:'Персонаж',items:'Предметы',other:'Другие данные'};
 const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const num=value=>value===null||value===undefined?'—':new Intl.NumberFormat('ru-RU',{maximumFractionDigits:Math.abs(Number(value))<100?1:0}).format(Number(value)||0);
 const compact=value=>value===null||value===undefined?'—':new Intl.NumberFormat('ru-RU',{notation:'compact',maximumFractionDigits:1}).format(Number(value)||0);
 const duration=value=>{const n=Math.max(0,Math.floor(Number(value)||0));return Math.floor(n/3600)+'ч '+String(Math.floor(n/60)%60).padStart(2,'0')+'м';};
 const live=state=>!!state?.settings?.enabled&&!!state?.engine?.ready&&state?.data?.context?.tracking!==false&&!!state?.data?.context?.inGame&&!!state?.data?.context?.sessionId&&!/^0{8}-/.test(state.data.context.sessionId);
 const status=state=>state?.error||state?.storage?.error||state?.engine?.warning||(state?.engine?.setup?'Первичная настройка':!state?.settings?.enabled?'Сбор выключен':!state?.engine?.ready?state?.engine?.message||'Подготовка…':state?.data?.context?.tracking===false?'Захват не запущен — проверьте настройки':live(state)?'Сессия записывается':'Ожидание входа в игру');
 window.SessionFormat={labels,modules,esc,num,compact,duration,live,status};
})();
